def rattacher_aux_consultations(apps, schema_editor):
    """Les demandes faites avant ce champ ne disent pas de quelle consultation
    elles viennent. On les rattache au rendez-vous du patient le jour de la
    demande — seulement s'il n'y en a qu'un : en cas de doute, rien."""
    from django.utils import timezone
    Demande = apps.get_model('laboratoire', 'DemandeExamen')
    RendezVous = apps.get_model('patients', 'RendezVous')
    for demande in Demande.objects.filter(rendez_vous__isnull=True):
        jour = timezone.localtime(demande.date_creation).date()
        rdvs = list(RendezVous.objects.filter(patient_id=demande.patient_id,
                                              date_heure__date=jour)[:2])
        if len(rdvs) == 1:
            demande.rendez_vous = rdvs[0]
            demande.save(update_fields=['rendez_vous'])


